tasks.command:
cd "${workspaceFolder}" && export AI_GATEWAY_API_KEY="$(grep -E '^AI_GATEWAY_API_KEY=' .env | head -1 | cut -d= -f2- | tr -d '\"')" && node --input-type=module <<'EOF'
const key = process.env.AI_GATEWAY_API_KEY;
if (!key) { console.log('INGEN AI_GATEWAY_API_KEY funnet'); process.exit(1); }
console.log('nokkel satt, lengde', key.length);
const base = 'https://ai-gateway.vercel.sh/v1';
const tools = [{ type: 'function', function: { name: 'get_weather', description: 'Get the weather for a city', parameters: { type: 'object', properties: { city: { type: 'string' } }, required: ['city'] } } }];
async function chat(model, messages, withTools) {
  const t0 = Date.now();
  const r = await fetch(base + '/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + key },
    body: JSON.stringify({ model, messages, max_tokens: 64, ...(withTools ? { tools } : {}) }),
  });
  const ms = Date.now() - t0;
  let j; try { j = await r.json(); } catch { j = { raw: await r.text().catch(()=> '') }; }
  return { status: r.status, ms, j };
}
const models = ['poolside/laguna-s-2.1-free', 'openai/gpt-5.4-mini'];
for (const model of models) {
  try {
    const a = await chat(model, [{ role: 'user', content: 'Svar kort: hva er 2+2?' }], false);
    console.log('\n[' + model + '] plain ->', a.status, a.ms + 'ms');
    console.log('  svar:', JSON.stringify(a.j?.choices?.[0]?.message?.content ?? a.j).slice(0, 160));
    const b = await chat(model, [{ role: 'user', content: 'Hva er vaeret i Oslo? Bruk verktoeyet.' }], true);
    const tc = b.j?.choices?.[0]?.message?.tool_calls;
    console.log('[' + model + '] tools ->', b.status, b.ms + 'ms', 'tool_calls=', JSON.stringify(tc ?? b.j?.error ?? null).slice(0, 220));
  } catch (e) { console.log('[' + model + '] FEIL:', e.message); }
}
EOF

cd "${workspaceFolder}" && export DSK="$(grep -E '^DEEPSEEK_API_KEY=' .env | head -1 | cut -d= -f2- | tr -d '\"\r')" && node --input-type=module <<'EOF'
const key = process.env.DSK;
console.log('deepseek-nokkel lengde', key ? key.length : 0, 'prefiks', key ? key.slice(0,6)+'...' : '-');
const base = 'https://api.deepseek.com/v1';
const tools = [{ type: 'function', function: { name: 'get_weather', description: 'Get the weather for a city', parameters: { type: 'object', properties: { city: { type: 'string' } }, required: ['city'] } } }];
async function chat(model, messages, withTools, max_tokens = 64) {
  const t0 = Date.now();
  const r = await fetch(base + '/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + key },
    body: JSON.stringify({ model, messages, max_tokens, ...(withTools ? { tools } : {}) }),
  });
  const ms = Date.now() - t0;
  let j; try { j = await r.json(); } catch { j = { error: 'no json' }; }
  return { status: r.status, ms, j };
}
for (const model of ['deepseek-chat']) {
  try {
    const a = await chat(model, [{ role: 'user', content: 'Svar kort: hva er 2+2?' }], false);
    const u = a.j?.usage;
    const cps = u ? Math.round((u.completion_tokens / (a.ms/1000))) : '?';
    console.log('[' + model + '] plain ->', a.status, a.ms + 'ms', 'tok/s=' + cps, '| svar:', JSON.stringify(a.j?.choices?.[0]?.message?.content ?? a.j?.error).slice(0,120));
    const b = await chat(model, [{ role: 'user', content: 'Hva er vaeret i Oslo? Bruk verktoeyet.' }], true);
    const tc = b.j?.choices?.[0]?.message?.tool_calls;
    console.log('[' + model + '] tools ->', b.status, b.ms + 'ms tool_calls=', JSON.stringify(tc ?? b.j?.error ?? null).slice(0,200));
  } catch (e) { console.log('[' + model + '] FEIL:', e.message); }
}
EOF
